function fetchMinimalShopifyIdentifiers() {
  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName("Your Google Sheet Name");
  const data = sheet.getDataRange().getValues();
  const shopifyToken = 'Your token';
  const shopDomain = 'Your Site URL';

  const skuMap = {};

  let url = `https://${shopDomain}/admin/api/2023-10/products.json?limit=250`;

  while (url) {
    const response = UrlFetchApp.fetch(url, {
      method: 'get',
      headers: { 'X-Shopify-Access-Token': shopifyToken },
      muteHttpExceptions: true,
    });

    if (response.getResponseCode() !== 200) {
      SpreadsheetApp.getUi().alert(`❌ HTTP ${response.getResponseCode()}: ${response.getContentText()}`);
      return;
    }

    const products = JSON.parse(response.getContentText()).products;

    for (let product of products) {
      for (let variant of product.variants) {
        const sku = variant.sku;
        if (!sku) continue;

        skuMap[sku] = {
          product_id: product.id,
          variant_id: variant.id,
          inventory_item_id: variant.inventory_item_id
        };
      }
    }

    const linkHeader = response.getAllHeaders()['Link'];
    const match = linkHeader && linkHeader.match(/<([^>]+)>; rel="next"/);
    url = match ? match[1] : null;
  }

  // Optional: Set headers in B–D (Row 1)
  sheet.getRange(1, 2, 1, 3).setValues([["product_id", "variant_id", "inventory_item_id"]]);

  for (let i = 1; i < data.length; i++) {
    const sku = data[i][0]; // Column A
    const match = skuMap[sku];

    if (match) {
      const rowData = [match.product_id, match.variant_id, match.inventory_item_id];
      sheet.getRange(i + 1, 2, 1, 3).setValues([rowData]); // Columns B–D
    }
  }

  SpreadsheetApp.getUi().alert("✅ Product, Variant, and Inventory IDs fetched using Column A SKUs.");
}

function fetchMinimalShopifyIdentifiers() {
  // === 🔧 CONFIGURATION & PLACEHOLDERS ===
  const shopDomain = 'YOUR_SHOPIFY_STORE.myshopify.com';
  const shopifyToken = 'YOUR_SHOPIFY_ACCESS_TOKEN';
  const SHEET_NAME = 'YOUR_SHEET_NAME';

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  if (!sheet) {
    SpreadsheetApp.getUi().alert(`❌ Sheet "${SHEET_NAME}" not found.`);
    return;
  }
  const data = sheet.getDataRange().getValues();

  const skuMap = {};

  let url = `https://${shopDomain}/admin/api/2023-10/products.json?limit=250`;

  while (url) {
    const response = UrlFetchApp.fetch(url, {
      method: 'get',
      headers: { 'X-Shopify-Access-Token': shopifyToken },
      muteHttpExceptions: true,
    });

    if (response.getResponseCode() !== 200) {
      SpreadsheetApp.getUi().alert(`❌ HTTP ${response.getResponseCode()}: ${response.getContentText()}`);
      return;
    }

    const products = JSON.parse(response.getContentText()).products;

    for (let product of products) {
      for (let variant of product.variants) {
        const sku = variant.sku;
        if (!sku) continue;

        skuMap[sku] = {
          product_id: product.id,
          variant_id: variant.id,
          inventory_item_id: variant.inventory_item_id
        };
      }
    }

    // Pagination header parsing
    let linkHeader = response.getAllHeaders()['Link'];
    if (Array.isArray(linkHeader)) linkHeader = linkHeader.join(',');
    const match = linkHeader && linkHeader.match(/<([^>]+)>; rel="next"/);
    url = match ? match[1] : null;
  }

  // Set column headers
  sheet.getRange(1, 2, 1, 3).setValues([["product_id", "variant_id", "inventory_item_id"]]);

  // Map IDs back to matching SKU rows
  for (let i = 1; i < data.length; i++) {
    const sku = data[i][0]; // Column A
    const match = skuMap[sku];

    if (match) {
      sheet.getRange(i + 1, 2, 1, 3).setValues([[match.product_id, match.variant_id, match.inventory_item_id]]);
    }
  }

  SpreadsheetApp.getUi().alert("✅ Product, Variant, and Inventory IDs fetched successfully.");
}

function updateshopifyPrices() {

  // === 🔧 CONFIGURATION ===
  const SHOPIFY_STORE = 'YOUR STORE URL';
  const ACCESS_TOKEN = 'YOUR TOKEN';  
  const SHEET_NAME = 'OMS & Other';

  const sheet = SpreadsheetApp.getActiveSpreadsheet().getSheetByName(SHEET_NAME);
  const data = sheet.getDataRange().getValues();

  for (let i = 1; i < data.length; i++) {

    const sku = data[i][0];                 // A INV Code
    const variantId = data[i][2];           // C variant_id
    const price = data[i][4];               // E SP
    const compareAtPrice = data[i][5];      // F MRP

    if (!variantId || price === "" || price === null) {
      sheet.getRange(i + 1, 7).setValue("⚠️ Missing Variant ID or Price");
      continue;
    }

    const url = `https://${SHOPIFY_STORE}/admin/api/2025-01/variants/${variantId}.json`;

    const payload = {
      variant: {
        id: Number(variantId),
        price: String(price),
        compare_at_price: compareAtPrice ? String(compareAtPrice) : null
      }
    };

    const options = {
      method: 'put',
      contentType: 'application/json',
      payload: JSON.stringify(payload),
      headers: { 'X-Shopify-Access-Token': ACCESS_TOKEN },
      muteHttpExceptions: true
    };

    try {

      const response = UrlFetchApp.fetch(url, options);
      const code = response.getResponseCode();
      const body = response.getContentText();

      if (code === 200) {
        sheet.getRange(i + 1, 7).setValue("✅ Success");
      }
      else if (code === 429) {
        Utilities.sleep(1500);
        i--;   // retry same row
      }
      else if (code === 401 || code === 403) {
        sheet.getRange(i + 1, 7).setValue("❌ Invalid Shopify token");
        Logger.log(body);
        return;
      }
      else {
        sheet.getRange(i + 1, 7).setValue("❌ Failed: " + body);
      }

    } catch (err) {
      sheet.getRange(i + 1, 7).setValue("❌ Error: " + err.message);
    }

    Utilities.sleep(500);   // Shopify safe delay

  }

  Logger.log("✅ Update completed.");
}

function buildComboList() {
  const ss = SpreadsheetApp.getActiveSpreadsheet();

  // === 🔧 CONFIGURATION & PLACEHOLDERS ===
  const SOURCE_ID = "YOUR_SOURCE_SPREADSHEET_ID";
  const SOURCE_RANGE = "Data Feed!A:I";
  const TARGET_SHEET_NAME = "Combo-Assemble";
  const POUCH_MAP_SS_ID = "YOUR_POUCH_MAP_SPREADSHEET_ID";
  const POUCH_MAP_SHEET_NAME = "YOUR_POUCH_SHEET_NAME";

  const COMBO_ITEMS = [
    { sku: "ITEM_SKU_1", unit: 1 },
    { sku: "ITEM_SKU_2", unit: 1 },
    { sku: "ITEM_SKU_3", unit: 48 }
  ];

  const sourceSS = SpreadsheetApp.openById(SOURCE_ID);
  const sourceSheet = sourceSS.getSheetByName("Data Feed");
  const data = sourceSheet.getRange(SOURCE_RANGE).getValues();

  // Load pouch size map dynamically from external sheet
  const pouchMapSS = SpreadsheetApp.openById(POUCH_MAP_SS_ID);
  const pouchMapSheet = pouchMapSS.getSheetByName(POUCH_MAP_SHEET_NAME);
  const pouchMapData = pouchMapSheet.getRange("B:AA").getValues();

  const POUCH_SIZE_MAP = {};
  const UNIT_MAP = {};

  pouchMapData.forEach(row => {
    const sku = row[0]; // Column B
    const pouch = row[9]; // Column K
    const unitVal = row[25]; // Column AA
    if (sku) {
      const skuStr = String(sku).trim();
      POUCH_SIZE_MAP[skuStr] = pouch ? String(pouch).trim() : "";

      // Parse unitVal and divide by 1000
      const parsedUnit = parseFloat(unitVal);
      UNIT_MAP[skuStr] = !isNaN(parsedUnit) ? parsedUnit * 1000 : null;
    }
  });

  const filtered = data
  .filter(r => r[0] === 1)
  .map(r => {
    const fullSKU = r[8].substring(0, 15);
    const shortSKU = fullSKU.substring(0, 6);

    let unit = UNIT_MAP[fullSKU];
    if (unit === null || unit === undefined) {
      unit = UNIT_MAP[shortSKU];
    }

    if (unit === null || unit === undefined) {
      const unitMatch = fullSKU.match(/(\d{6})BP$/);
      unit = unitMatch ? parseInt(unitMatch[1], 10) : 0;
    }

    return { fullSKU, unit };
  });

  const output = [];
  output.push(["SKU", "Product ID", "Is Master", "Unit", "Master SKU ID"]);
  let rowCount = 2;

  filtered.forEach(item => {
    // Row 1: 15 chars SKU (MASTER)
    output.push([
      item.fullSKU,
      `=XLOOKUP($A${rowCount},'Current OMS Product Data'!$I:$I,'Current OMS Product Data'!$A:$A,"")`,
      "Reference Only",
      "Reference Only",
      `=B${rowCount}` // MASTER SKU ID
    ]);
    let masterRow = rowCount; // store master row index
    rowCount++;

    // Row 2: short SKU
    const shortSKU = item.fullSKU.substring(0, 6);
    output.push([
      shortSKU,
      `=XLOOKUP($A${rowCount},'Current OMS Product Data'!$I:$I,'Current OMS Product Data'!$A:$A,"")`,
      1,
      item.unit,
      `=B${masterRow}` // ALL CHILD ROWS USE MASTER ID
    ]);
    rowCount++;

    // Row 3: PB/BP SKU
    const pbSKU = POUCH_SIZE_MAP[item.fullSKU] || "";
    output.push([
      pbSKU,
      `=XLOOKUP($A${rowCount},'Current OMS Product Data'!$I:$I,'Current OMS Product Data'!$A:$A,"")`,
      0,
      1,
      `=B${masterRow}` // uses master ID
    ]);
    rowCount++;

    // Combo items
    COMBO_ITEMS.forEach(ci => {
      output.push([
        ci.sku,
        `=XLOOKUP($A${rowCount},'Current OMS Product Data'!$I:$I,'Current OMS Product Data'!$A:$A,"")`,
        0,
        ci.unit,
        `=B${masterRow}` // uses master ID
      ]);
      rowCount++;
    });
  });

  let targetSheet = ss.getSheetByName(TARGET_SHEET_NAME);
  if (!targetSheet) {
    targetSheet = ss.insertSheet(TARGET_SHEET_NAME);
  } else {
    targetSheet.clear();
  }
  targetSheet.getRange(1, 1, output.length, output[0].length).setValues(output);
  SpreadsheetApp.getUi().alert("Combo List Built Successfully!");
}

function onOpen() {
  SpreadsheetApp.getUi()
  .createMenu("Combo Tools")
  .addItem("▶️ Build Combo List", "buildComboList")
  .addToUi();
}
